SELECT product_id, CASE WHEN revenue >= 3600 THEN 'high' WHEN revenue >= 2000 THEN 'mid' ELSE 'low' END AS revenue_bucket, COUNT(units) AS units_count, ROUND(STDDEV(revenue), 2) AS stddev_revenue FROM store_sales WHERE (MONTH(sale_date) IN (7, 10, 11) AND revenue >= 1600) OR sale_date BETWEEN '2024-08-01' AND '2024-11-01' GROUP BY product_id, revenue_bucket ORDER BY stddev_revenue DESC
